use crate::tokenize;

use super::token::{LiteralTokenType, NumberBase, RawStringError, Token, TokenType};
use super::tokenizer::Tokenizer;
use super::*;

/// Assert that the tokens generated by `tokenize` match the expected tokens.
macro_rules! assert_tokenize_eq_roundtrip {
    ($src:expr, $($expected:expr),* $(,)?) => {
        // tokenize
        let tokens: Vec<_> = tokenize($src).collect();
        // must match the expected tokens
        let expected_tokens = vec![$($expected),*];
        assert_eq!(tokens, expected_tokens);
        // render back to input string
        let rendered_input = render_tokens(&tokens, $src);
        assert_eq!(rendered_input, $src);
        // re-tokenize on the rendered input
        let tokens_again: Vec<_> = tokenize(&rendered_input).collect();
        assert_eq!(tokens_again, tokens);
    };
}

/// Tokenize, render, and re-tokenize an input string in a roundtrip.
macro_rules! assert_tokenize_roundtrip {
    ($input:expr) => {
        // tokenize & render back to input string
        let tokens: Vec<_> = tokenize($input).collect();
        let rendered_input = render_tokens(&tokens, $input);
        assert_eq!(rendered_input, $input);
        // tokenize again on the rendered input and compare directly
        let tokens_again: Vec<_> = tokenize(&rendered_input).collect();
        assert_eq!(tokens_again, tokens);
    };
}

/// Check whether a raw string tokenizes as expected.
fn assert_raw_str_eq(s: &str, expected: Result<u8, RawStringError>) {
    let s = &format!("r{s}");
    let mut cursor = Tokenizer::new(s);
    cursor.bump();
    let res = cursor.raw_double_quoted_string(0);
    assert_eq!(res, expected);
}

#[test]
fn test_naked_raw_str() {
    assert_raw_str_eq(r#""abc""#, Ok(0));
}

#[test]
fn test_raw_no_start() {
    assert_raw_str_eq(r##""abc"#"##, Ok(0));
}

#[test]
fn test_too_many_terminators() {
    // this error is handled in the parser later
    assert_raw_str_eq(r###"#"abc"##"###, Ok(1));
}

#[test]
fn test_unterminated() {
    assert_raw_str_eq(
        r#"#"abc"#,
        Err(RawStringError::NoTerminator {
            expected: 1,
            found: 0,
            possible_terminator_offset: None,
        }),
    );
    assert_raw_str_eq(
        r###"##"abc"#"###,
        Err(RawStringError::NoTerminator {
            expected: 2,
            found: 1,
            possible_terminator_offset: Some(7),
        }),
    );
    // we're looking for "# not just any #
    assert_raw_str_eq(
        r###"##"abc#"###,
        Err(RawStringError::NoTerminator {
            expected: 2,
            found: 0,
            possible_terminator_offset: None,
        }),
    )
}

#[test]
fn test_valid_weird_unicode() {
    assert_tokenize_eq_roundtrip!(
        "\u{3}\n",
        Token {
            r#type: TokenType::Unknown,
            len: 1
        },
        Token {
            r#type: TokenType::Whitespace,
            len: 1
        }
    );
}

#[test]
fn test_invalid_start() {
    assert_raw_str_eq(
        r##"#~"abc"#"##,
        Err(RawStringError::InvalidStarter { bad_char: '~' }),
    );
}

