#[test]
fn test_raw_string() {
    assert_tokenize_eq_roundtrip!(
        "r###\"\"#a\\b\x00c\"\"###",
        Token {
            r#type: TokenType::Literal {
                r#type: LiteralTokenType::RawString { hashes: Some(3) },
                suffix_start: 17
            },
            len: 17
        },
    );
}

